insert into public.product_type (name, category_id, base_unit) select 'Tapete higiênico', (select id from public.category where name_normalized = public.normalize_name('Pet')), 'unit' where not exists (select 1 from public.product_type where name_normalized = public.normalize_name('Tapete higiênico'));

