-- 7. Generic brandless registrations, one leaf each: by weight with no
--    packaging for Peso, Volume and Tamanho, 1 x 1 un for Contagem.
with new_registration as (insert into public.product_registration (product_type_id, description, selling_mode) select (select id from public.product_type where name_normalized = public.normalize_name('Banana')), 'maçã', 'by_weight' where not exists (select 1 from public.product_registration where product_type_id = (select id from public.product_type where name_normalized = public.normalize_name('Banana')) and brand_id is null and description_normalized = public.normalize_name('maçã')) returning id) insert into public.product (product_registration_id) select id from new_registration;
